items.statement:
Fix $n_G\ge1$ and a closed subgroup $G\subset U(n_G)$ with simple nonabelian real Lie algebra
\begin{equation*}
\g=\{X\in M_{n_G}(\C):\exp(tX)\in G\text{ for every }t\in\R\},
\qquad \langle X,Y\rangle_\g=-n_G^{-1}\operatorname{Re}\tr(XY)\,.
\end{equation*}
For an orthonormal basis $(e_\alpha^{\g})$, put
\begin{align*}
\dimG&=\dim_\R\g,&
\casimir&=-\dimG^{-1}\sum_\alpha\operatorname{tr}_{\g}\bigl(\operatorname{ad}(e_\alpha^{\g})^2\bigr),\\
b_0&=\frac{11\casimir}{48\pi^2},& \slope&=2b_0\,.
\end{align*}
This fixes the normalization of the running coupling.

For a label list $v\in\mathcal T^n$, sites $y\in\Lambda_{L_pD_N}^n$, and a test $f:(\R^4)^n\to\C$, define
\begin{align*}
\latmoment_{N,p}(v;y)&=\int\prod_{i=1}^n I_{N,p}(v_i,y_i;U)\,d\mu_{N,p}(U),\\
\latsmear_{N,p}(v;f)&=a_N^{4n}\sum_{y\in\Lambda_{L_pD_N}^n}f(\hat y)\latmoment_{N,p}(v;y)\,.
\end{align*}
These are the point correlations and their physical Riemann sums.

For fine links $U$ and coarse links $V$, define
\begin{align*}
\blockkernel{m}_\beta(U,V)
&=\sum_{\alpha_{\rm tag}}\lambda^{\rm tag}(U,\alpha_{\rm tag})
\prod_{e\ {\rm coarse}}
\frac{e^{-\blockpenalty\beta\wilsonterm(V_eQ_e^{\rm pred}(U,\alpha_{\rm tag})^{-1})}}
{\int_G e^{-\blockpenalty\beta\wilsonterm(u)}\,dh(u)},\\
(\blockmap{m}_\beta f)(V)&=\int\blockkernel{m}_\beta(U,V)f(U)\,dU\,.
\end{align*}
Both product measures are probability Haar measures, and $\int\blockkernel{m}_\beta(U,V)\,dV=1$. The map integrates one scale without changing the partition integral.

\operatorname{clip}_{t}(r)&=
\begin{cases}c_{\rm dir}r^2/2,&r\le t,\\c_{\rm lin}tr,&r>t,\end{cases}\\
\chi^{\rm hlth}_{m,x}(U)&=\mathbf1\!\left\{
\chord(U_{y;ab})\le t_m e^{\operatorname{dist}(x,y)/R_{J_m}^{\rm rel}}
\text{ for every }y,a<b\right\}\,.

For a regular activity anchored at $o_i$, set
\begin{equation*}
\|E_i^{\rm reg}\|_m=
\sup_{0\le q\le\mathfrak q_{J_m}}\ \sup_{U,\dot{\mathcal A}_1,\ldots,\dot{\mathcal A}_q}
\bigl|D^L_{\dot{\mathcal A}_1}\cdots D^L_{\dot{\mathcal A}_q}E_i^{\rm reg}(U)\bigr|\,.
\end{equation*}
The second supremum is over configurations healthy on $X_i$ and directions satisfying
\begin{equation*}
|(\dot{\mathcal A}_k)_e|\le t_m\bigl(1+\operatorname{dist}(e^-,o_i)\bigr)^{\varpi_{J_m}}\qquad\text{for }1\le k\le q\,.
\end{equation*}
This measures ordered local derivatives in units of the permitted field size.

For nonnegative majorants $e_i^{\rm maj}\ge\|E_i^{\rm reg}\|_m$ and $k_i^{\rm maj}\ge\sup_U|K_i^{\rm for}(U)|$, define
\begin{align*}
\mathcal E_m&=\sup_x\sum_{o_i=x}e^{\sigma_{J_m}\cover_{B_m}(X_i)}e_i^{\rm maj},\\
\mathcal K_m&=\sup_x\sum_{x\in Y_i}e^{\sigma_{J_m}\cover_{B_m}(Y_i)}k_i^{\rm maj}\,.
\end{align*}
These sums measure regular and forced terms separately, with a penalty for large supports.

For every $N,p$, $m<N$, reals $u_0\le u_1$ and continuous $\rho'_u\in\mathcal A_{N,m+1,p}$ with $\beta'_u=\beta(\rho'_u)\in\mathfrak B_{m+1}$ for all $u\in[u_0,u_1]$, there is a continuous $\rho_u\in\mathcal A_{N,m,p}$ with $(\rho_u,\rho'_u)\in\mathcal R_{N,m,p}$ and, for every $u\in[u_0,u_1]$ and coarse configuration $V$,
\begin{align*}
\density\rho_u(V)&=(\blockmap{m}_{\beta'_u}\density\rho'_u)(V),\\
\beta(\rho_u)&=\beta'_u-\slope\log\ell_m+e_u,
\qquad |e_u|\le\omega_{J_{m+1}}^{\rm RG}\,.
\end{align*}

There are bare couplings $\beta_{N,p}$ and trajectories $(\rho_{N,p,m})_{m=0}^N$, for all $N,p\in\N$, with $\rho_{N,p,N}=\rho^{\rm W}_{\beta_{N,p}}$ and $\beta_{N,p,N}=\beta_{N,p}$, satisfying
\begin{gather*}
\beta_{N,p,0}=\bar\beta,\qquad \beta_{N,p,m}\in\mathfrak B_m\quad(0\le m\le N),\\
\density\rho_{N,p,m}=\blockmap{m}_{\beta_{N,p,m+1}}\density\rho_{N,p,m+1}\quad(m<N)\,.
\end{gather*}
For every $\varepsilon>0$, some $m_0(\varepsilon)$ satisfies
\begin{equation*}
|\beta_{N,p,m}-\slope s_m|\le\varepsilon s_m
\qquad(N\ge m\ge m_0,\ p\in\N)\,.
\end{equation*}

There is a width $w_{\rm tun}>0$, independent of~$N,p$, such that, for every~$N,p$ and $s\in[-1,1]$, exactly one bare coupling~$\beta_{N,p}(s)$ starts a trajectory of the specified recursion reaching $\bar\beta+w_{\rm tun}s$ at level zero. It satisfies $\beta_{N,p}(0)=\beta_{N,p}$ and has a holomorphic extension~$b_{N,p}$ to $|z|<1$ with
\begin{equation}
b_{N,p}(s)=\beta_{N,p}(s)\qquad(-1<s<1)\,.
\end{equation}

Let $\mathcal J$ consist of formal $\g$-valued arrays $\mathcal A_a(x)=\sum_{k\ge0}\mathcal A_{k,a}(x)$, with $\mathcal A_{k,a}$ homogeneous of degree $k+1$ and
\begin{equation*}
\sum_a x^a\mathcal A_{k,a}(x)=0,\qquad
V_d=\C[\mathcal J]^{\operatorname{Ad}(G)}_{\mathrm{weight}\le d}\,.
\end{equation*}
Each coordinate of $\mathcal A_k$ has bidegree $(k+2,1)$: engineering weight and number of polynomial factors. Fix bihomogeneous bases, the supremum coefficient norm, conjugation and the induced $\hypercubic$ action. These labels describe invariant curvature polynomials; curvature has weight two and a covariant derivative adds one.

Put $\mathcal T=\bigsqcup_{d\ge0}V_d$ and define, at every cutoff,
\begin{equation*}
I_{N,p}((d,\mathbf c),y;U)=O^{(d)}_{N,p}(\mathbf c,y;U)
=a_N^{-d}\localsection{d}[\factorscale_{t_N^{-1}}\mathsf Z_{N,p,d}^{-1}\mathbf c](y;U)\,.
\end{equation*}
This fixes the insertion along the trajectory. Its distinguished unit coefficient is $\mathbf u_d=a_{\reflevel{d}}^d\mathbf1$, whose insertion equals one for $N\ge\reflevel{d}$. The scaling $\factorscale_t$ counts factors, not engineering weight.

For every $v\in\mathcal T^n$, finite difference list~$\boldsymbol l$ and $r>0$, there are $B(v,\boldsymbol l,r)\ge0$ and $N_0(v,\boldsymbol l,r)$ such that, for every $N\ge N_0$, every~$p$ and every lattice tuple of torus separation at least~$r$,
\begin{equation*}
|\Delta_{\boldsymbol l}\latmoment_{N,p}(v;y)|\le B\,.
\end{equation*}

For every $p,n$ and $v\in\mathcal T^n$, there is $M^{\rm UV}_{p,v}\in C^\infty(\NoHit{L_p}{n})$ such that, for every finite~$\boldsymbol l$ and every $p$-admissible separated test~$f$,
\begin{equation*}
\lim_{N\to\infty}a_N^{4n}\sum_{y\in\Lambda_{L_pD_N}^n}f(\hat y)\Delta_{\boldsymbol l}\latmoment_{N,p}(v;y)
=\int f(x)\partial_{\boldsymbol l}M^{\rm UV}_{p,v}(x)\,dx\,.
\end{equation*}

A Wilson family converges to~$K$ along~$P:\N\to\N$ if, for every $n,v$ and separated test~$f$, the test is eventually $P(k)$-admissible and there are numbers $C_p^{\rm UV}(v;f)$ with
\begin{align*}
\latsmear_{N,p}(v;f)&\longrightarrow C_p^{\rm UV}(v;f)\quad(N\to\infty)
&&\text{at every admissible }p,\\
C_{P(k)}^{\rm UV}(v;f)&\longrightarrow\int f(x)K_n(v;x)\,dx\,.
\end{align*}

E1 is simultaneous permutation symmetry, $S_0=1$ and deletion of a slot carrying~$\mathbf u_d$. E2 is
\begin{equation*}
S_n(hc;hx)=S_n(c;x)\quad(h\in\hypercubic),\qquad
S_n(\bar c;x)=\overline{S_n(c;x)}\,.
\end{equation*}
E3 is translation invariance.

E4 requires, for every axis~$a$, positive-side separated words~$w_i$ and complex coefficients~$z_i$,
\begin{equation*}
\sum_{i,j}\bar z_i z_jS(\mathsf s_a^{\rm refl}w_i^*w_j)\ge0\,.
\end{equation*}
The star reverses the word and applies conjugation to its labels; $\mathsf s_a^{\rm refl}$ reflects positions and acts on labels through~$\hypercubic$. E5 requires the same positivity for finite sums of words smeared against joint smooth compactly supported tests on positive-side separated configurations, and absolute integrability of every mixed pairing.

E6 is smoothness on~$\Conf{n}$. E7 requires, for each $n,d_i,c_i,k$, constants $C(n,d,c,k)\ge0$ and an integer $A(n,d,c,k)\ge0$ such that
\begin{equation*}
\|D_x^kS_n(c;x)\|\le Cr^{-A}
\qquad(0<r\le1,\ \sepinf(x)\ge r)\,.
\end{equation*}

For the table~$S$ of Theorem~\ref{prop:IV}, there are complex linear maps $\jmath_{d,e}:F_d\to F_e$ for $d\le e$ and $\partial_a:F_d\to F_{d+1}$ for every $d,a$ such that, for every $A\in F_d$,
\begin{gather*}
\iota_e\circ\jmath_{d,e}=\iota_d,\qquad
\iota_{d+1}(\partial_aA)=\partial_{x_0^a}\iota_d(A),\\
\dim_\C F_d=\dim_\C\maxwellspace{d}\,.
\end{gather*}

A scaling sequence consists of $r_k>0$, $r_k\to0$, and complex linear isomorphisms
\begin{equation*}
\scaleframe{k}{d}:\maxwellspace{d}\longrightarrow F_d\,.
\end{equation*}
It is stable if, for every $D\in\N$, these maps eventually preserve conjugation, $\hypercubic$, units and inclusions exactly in all degrees $d\le e\le D$. Scaling dimensions are included in the maps: an ordinary comparison insertion is $\scaleframe{k}{d}u$ at~$r_kx$, with no further factor~$r_k^d$.

There is one stable scaling sequence such that, for every arity~$n$, degree list $(d_i)$ and $u_i\in\maxwellspace{d_i}$,
\begin{equation*}
S_n(\scaleframe{k}{d_i}u_i;r_k\,\cdot\,)\longrightarrow\maxwellcorr_n(u;\cdot)
\quad\text{in }L^1_{\rm loc}(\Conf{n})\,.
\end{equation*}

There is a real symmetric $O(4)$-tensorial family $T_{ab}\in F_4$ with $\sum_a\partial_aT_{ab}=0$ such that, for every degree, field, spectator list, separated configuration and shell cutoff of Definition~\ref{def:D13}, every~$b$ and every $K_{\rm rot}\in\mathfrak{so}(4)$,
\begin{equation*}
\mathcal P_b^T=\partial_{x_0^b}S(A(x_0),\boldsymbol B(x)),\qquad
\mathcal Y_{K_{\rm rot}}^T=S((\mathsf L_d(K_{\rm rot})A)(x_0),\boldsymbol B(x))\,.
\end{equation*}

Along the refinement of the scaling sequence of Proposition~\ref{prop:MC} chosen in Lemma~\ref{lem:G2.2}, for every fixed free list and stress-slot choice, every derivative order~$j$ and compact $\mathcal K\subset\Conf{n}$, with $A_{k,i}=r_k^4T_{a_ib_i}$ on~$I$ for the fixed tensor of Theorem~\ref{prop:ST} and $A_{k,i}=\scaleframe{k}{d_i}u_i$ elsewhere,
\begin{equation*}
D_x^jS_n(\boldsymbol A_k;r_kx)\longrightarrow D_x^j\maxwellcorr_n(\boldsymbol A^0;x)
\quad\text{uniformly on }\mathcal K\,.
\end{equation*}

For words at distinct points in $x^a>0$, let $\mathcal H_a^{\rm OS}$ be the completion of their complex span modulo the null space of
\begin{equation*}
\langle w,v\rangle_a=S(\mathsf s_a^{\rm refl}w^*v),\qquad e^{-tH_a^{\rm OS}}[v]=[\tau_{te_a}v]\quad(t\ge0)\,.
\end{equation*}
By E4 the form is positive semidefinite; with E7, the translations $\tau_{te_a}$, $t\ge0$, preserve its null space and define a strongly continuous self-adjoint contraction semigroup, whose generator is $H_a^{\rm OS}\ge0$ (proof of Lemma~\ref{lem:H1.1}).
Let $\Omega_a^{\rm OS}$ be the empty-word vector and $P^0_a$ the projection onto $\ker H_a^{\rm OS}$. For $h_{\rm sl}>0$ and $w$ with times in $(0,h_{\rm sl})$, define, on positive-time words $v$,
\begin{equation*}
A_wv=w\,\tau_{h_{\rm sl}e_4}v,\qquad M^0(w)=P^0_4\mathsf B_{h_{\rm sl}}(w)|_{\ker H_4^{\rm OS}}\,,
\end{equation*}
where $\mathsf B_{h_{\rm sl}}(w)$ extends $A_w$ boundedly on OS classes, by Lemma~\ref{lem:H1.1}.

The algebra $\mathfrak A_0$ has a compact metric character space $\phases$ with a full-support probability measure $\nu$ such that, for every separated word $w$,
\begin{equation*}
S^\xi(w)=\xi(M^0(w)),\qquad S(w)=\int_{\phases}S^\xi(w)\,d\nu(\xi)\,.
\end{equation*}
Each phase satisfies E1--E7 and has exactly the null spaces $\nullspace{d}(S^\xi)=\nullspace{d}(S)$. The identities of FC, $O(4)$ covariance and ST hold with $S^\xi$ in place of $S$, for the same maps and tensor $T$. For fixed $w$, $\xi\mapsto S^\xi(w)$ is continuous.

For every $\psi\in\mathcal H$ and $z\in\R^4$, require
\begin{equation*}
\langle\psi,\mathsf T(z)\psi\rangle=\int e^{i\mathbf p\cdot z}\,d\mu_\psi(\mathbf p),\qquad \mathsf E(\R^4\setminus\forwardcone)=0\,,
\end{equation*}
with Euclidean pairing. Every vector fixed by all translations belongs to $\C\Omega$.

Require $\|\Omega\|=1$, density of $\mathcal D$, and
\begin{equation*}
\mathcal D=\operatorname{span}_{\C}\{\Phi(\ell_1,f_1)\cdots\Phi(\ell_k,f_k)\Omega:k\ge0\}\,.
\end{equation*}
For each $\ell\in\mathcal L$, $\psi\in\mathcal D$, the map $f\mapsto\Phi(\ell,f)\psi$ is continuous from $\mathcal S$ to $\mathcal H$ in norm. For $\psi,\chi\in\mathcal D$, require $\langle\Phi(\ell,f)\psi,\chi\rangle=\langle\psi,\Phi(\ell^*,\bar f)\chi\rangle$.

Require $\rho_{\rm lab}(1)=1$ and $\rho_{\rm lab}(\gamma\gamma')=\rho_{\rm lab}(\gamma)\rho_{\rm lab}(\gamma')$. For every $\gamma\in\mathcal P$, $\ell\in\mathcal L$, $f\in\mathcal S$ and $\psi\in\mathcal D$, require $\mathsf U(\gamma)\mathcal D\subset\mathcal D$, $\mathsf U(\gamma)\Omega=\Omega$, and
\begin{equation*}
\mathsf U(\gamma)\Phi(\ell,f)\psi=\Phi(\rho_{\rm lab}(\gamma)\ell,\gamma\cdot f)\mathsf U(\gamma)\psi\,.
\end{equation*}

For a phase $\xi$, a relativistic datum $(\mathcal H_\xi,\mathcal L,\mathcal D_\xi,\Omega_\xi,\Phi_\xi,\ldots)$ of Definitions~\ref{def:D14a}--\ref{def:D14b}, linear maps $\iota_d:F_d\to\mathcal L$, and functions $\mathsf F_n^\xi$ on $\mathbb F^n\times\C^n\times(\R^3)^n$, require, for every $n\in\N$, $\boldsymbol A\in\mathbb F^n$, real $h_1<\cdots<h_n$ and $f_i\in\mathcal S$,
\begin{multline*}
\lim_{r\downarrow0}\int\mathsf F_n^\xi(\boldsymbol A;(x_i^4+irh_i)_i,(\vec x_i)_i)\prod_i f_i(x_i)\,dx\\
=\langle\Omega_\xi,\Phi_\xi(\iota(A_1),f_1)\cdots\Phi_\xi(\iota(A_n),f_n)\Omega_\xi\rangle\,.
\end{multline*}
For this formula alone a nonintegrable function has integral zero, as in the formal statement. For the continuations constructed in Theorem~\ref{prop:RC} the integrands are integrable for every $r>0$ (Section~\ref{sec:partII-H}).

For a phase~$\xi$, put $\mathcal Z_n=\{z\in\C^n:\operatorname{Im}z_1<\cdots<\operatorname{Im}z_n\}$. A continuation~$\mathsf F_n^\xi$ is holomorphic there at each fixed real spatial configuration and satisfies
\begin{equation*}
\mathsf F_n^\xi(\boldsymbol A;(it_i)_i,\vec x)=S_n^\xi(\boldsymbol A;(\vec x_i,t_i)_i)\qquad(t_1<\cdots<t_n)\,.
\end{equation*}
Together with Definition~\ref{def:D14f}, it connects Euclidean and real-time correlations.

For every $\xi\in\phases$, there are a faithful Wightman theory (Definition~\ref{def:wightman}) on $\mathcal L$ and functions $\mathsf F_n^\xi$ satisfying Definitions~\ref{def:D15} and~\ref{def:D14f} with the response maps $\iota_d$ of Definition~\ref{def:D10}. Its OS comparison map $\mathsf J_\xi^{\rm OS}$ is unitary, intertwines spatial translations and satisfies $\mathsf J_\xi^{\rm OS}e^{-sH_\xi}=e^{-sH_{4,\xi}^{\rm OS}}\mathsf J_\xi^{\rm OS}$ for $s\ge0$, and
\begin{equation*}
\ker H_\xi=\C\Omega_\xi,\qquad \ker H_{4,\xi}^{\rm OS}=\C\Omega_\xi^{\rm OS}\,.
\end{equation*}
Every bounded operator in the weak commutant of its fields is scalar.

For the tensor $T$ fixed after Theorem~\ref{prop:ST} and $r>0$, put
\begin{align*}
\tau&=\sum_{a=1}^4T_{aa},&e_{\rm tr}&=S^{\xi_*}(\tau),&\Theta&=\tau-e_{\rm tr}\unitfield{4},\\
\tracetwopoint(r)&=S_2^{\xi_*}(\Theta,\Theta;-re_4/2,re_4/2),&\traceamplitude&=\frac{3\dimG}{\pi^4}\,.
\end{align*}
The one-point value is position independent. Centering removes the vacuum contribution in the selected phase.

The selected field $\Theta$ is nonzero, real and $O(4)$ invariant; its label $\iota_4\Theta$ is Hermitian and Lorentz scalar (Definition~\ref{def:D14e}). For every $f\in\mathcal S$,
\begin{equation*}
\langle\Omega,\Phi(\iota_4\Theta,f)\Omega\rangle=0\,.
\end{equation*}
As $r\downarrow0$ through all positive radii,
\begin{equation*}
\lim_{r\downarrow0}r^8\log^2(1/r)\tracetwopoint(r)=\traceamplitude>0\,.
\end{equation*}

Put $\omega_{m_{\rm sh}}(\mathbf k)=\sqrt{m_{\rm sh}^2+|\mathbf k|^2}$ and, for $r>0$,
\begin{equation*}
K_{m_{\rm sh},k_E,h_{\rm mom}}(r)=\int_{\R^3}\frac{\omega_{m_{\rm sh}}(\mathbf k)^{k_E}h_{\rm mom}(\mathbf k)}{2\omega_{m_{\rm sh}}(\mathbf k)}e^{-r\omega_{m_{\rm sh}}(\mathbf k)}\,d^3\mathbf k\,.
\end{equation*}
A finite Wick profile is a function
\begin{equation*}
W_{\rm Wick}(r)=\sum_{i=1}^{N}c_i\prod_{j=1}^{n_i}K_{m_{ij},k_{ij},h_{ij}}(r)\quad(r>0),\qquad c_i\in\C\,,
\end{equation*}
with finitely many terms and factors of the preceding kind; empty products are one.

For every finite Wick profile $W_{\rm Wick}$ and every $\delta>0$, there is $0<r<\delta$ such that
\begin{equation*}
\tracetwopoint(r)\ne W_{\rm Wick}(r)\,.
\end{equation*}

For finite index sets $I_{\rm cl},I_{\rm sp}$ and $D\in\N$, cluster and spectator lists $\boldsymbol A\in\mathbb F^{I_{\rm cl}}$, $\boldsymbol B\in\mathbb F^{I_{\rm sp}}$, put $|\boldsymbol A|_{\deg}=\sum_i\deg A_i$ and
\begin{equation*}
\mathcal R_D^\zeta=S^\zeta(\boldsymbol A,x;\boldsymbol B,y)-\sum_{j=0}^D\sum_{\lambda\in\channels{j}}c_{j,\lambda}(\boldsymbol A;x,o)S^\zeta(O_{j,\lambda}(o),\boldsymbol B(y))\,.
\end{equation*}
Use a fixed enumeration of $I_{\rm cl}\sqcup I_{\rm sp}$ for the concatenated correlations. A pair $(x,o)$ is an $(r,M_{\rm geo},\eta)$-cluster if $|x_i-o|\le M_{\rm geo}r$ and $|x_i-x_{i'}|\ge\eta r$ for distinct slots. Spectators are $\delta_{\rm sp}$-clear if $|o-y_j|\ge\delta_{\rm sp}$ and $|y_j-y_{j'}|\ge\delta_{\rm sp}$ for distinct slots. The remainder measures the error through degree $D$.

For every finite list $\boldsymbol A$, $M_{\rm geo}\ge0$, $\eta,\varepsilon>0$, $j\in\N$ and $\lambda\in\channels{j}$, some $r_0>0$ gives, for $0<r<r_0$ and every $(r,M_{\rm geo},\eta)$-cluster,
\begin{equation*}
|c_{j,\lambda}(\boldsymbol A;x,o)|\le r^{j-|\boldsymbol A|_{\deg}-\varepsilon}\,.
\end{equation*}
For every pair of finite lists $\boldsymbol A,\boldsymbol B$, $M_{\rm geo}\ge0$, $\eta,\delta_{\rm sp},\varepsilon>0$ and $D\in\N$, some $r_1>0$ gives, for $0<r<r_1$, such clusters, $\delta_{\rm sp}$-clear spectators and all state indices~$\zeta$,
\begin{equation*}
|\mathcal R_D^\zeta|\le r^{D+1-|\boldsymbol A|_{\deg}-\varepsilon}\,.
\end{equation*}

For every state index $\zeta$, arity $n$ and list $\boldsymbol A\in\mathbb F^n$, the contact construction of Section~\ref{sec:partII-J}, \ref{sec:partII-J.2}, fixed on the underlying prescription of Lemma~\ref{lem:J1.1}, gives a distribution $\mathfrak D_{\boldsymbol A}^\zeta$ on $\R^{4n}$ such that, for every separated test $f$,
\begin{equation*}
\mathfrak D_{\boldsymbol A}^\zeta(f)=\int f(x)S_n^\zeta(\boldsymbol A;x)\,dx\,.
\end{equation*}

Hierarchy data over~$\mathcal W$ consist of:
\begin{itemize}[nosep]
\item complex Hilbert and vector spaces~$\mathcal H,\mathcal L$, and the relativistic data of Definitions~\ref{def:D14a}--\ref{def:D14b};
\item finite-dimensional complex normed spaces~$F_d$, linear maps~$\iota_d:F_d\to\mathcal L$, and $\pi_{\rm quo}:\mathcal T\to\mathbb F$, where $\mathbb F=\bigsqcup_dF_d$;
\item a compact metric space~$\phases$, a Borel measure~$\nu$ and $\xi_*\in\phases$;
\item functions $S_n^\zeta:\mathbb F^n\times(\R^4)^n\to\C$ for $\zeta\in\phases\sqcup\{\mathrm{mix}\}$, and $\mathsf F_n:\mathbb F^n\times\C^n\times(\R^3)^n\to\C$;
\item finite sets~$\channels{j}$, fields~$O_{j,\lambda}\in F_j$, and coefficients $c_{j,\lambda}:\mathbb F^{I_{\rm cl}}\times(\R^4)^{I_{\rm cl}}\times\R^4\to\C$ for every finite index set~$I_{\rm cl}$;
\item an element~$\Theta\in F_4$.
\end{itemize}

A Wilson family is regular if its insertions are continuous and gauge invariant, each token~$v$ has a finite stencil~$\Sigma_v\subset\Z^4$ valid for every~$N,p,y$, and some~$b_*>0$ satisfies
\begin{equation*}
\forall\varepsilon>0\ \exists N_0\ \forall N\ge N_0\ \forall p:\quad
\left|\frac{\beta_{N,p}}{\log(1/a_N)}-b_*\right|<\varepsilon\,.
\end{equation*}
Only links with both ends in~$y+\Sigma_v$ modulo the torus are read.

Every nonzero~$\ell\in\mathcal L$ has $\Phi(\ell,f)\ne0$ for some~$f\in\mathcal S$. Each~$\iota_d$ is injective, their images cover~$\mathcal L$, $\pi_{\rm quo}$ is onto, and $\Phi(\iota(A),f)\ne0$ for some~$A\in\mathbb F$, $f\in\mathcal S$. The measure~$\nu$ is a probability measure of full support. Each~$S_n^\zeta$ is simultaneously permutation symmetric and smooth on~$\Conf{n}$. For every $n$, $\boldsymbol A\in\mathbb F^n$ and $x\in\Conf{n}$,
\begin{equation*}
\xi\longmapsto S_n^\xi(\boldsymbol A;x)\text{ is continuous},\qquad
S_n^{\rm mix}(\boldsymbol A;x)=\int_{\phases}S_n^\xi(\boldsymbol A;x)\,d\nu(\xi)\,.
\end{equation*}

For the chosen~$\Theta\in F_4$, put
\begin{equation*}
\tracetwopoint(r)=S_2^{\xi_*}(\Theta,\Theta;-re_4/2,re_4/2),\qquad
\traceamplitude=\frac{3\dimG}{\pi^4}\,.
\end{equation*}
Require
\begin{equation*}
\langle\Omega,\Phi(\iota_4\Theta,f)\Omega\rangle=0\qquad(f\in\mathcal S)\,,
\end{equation*}
and
\begin{equation*}
\lim_{r\downarrow0}r^8\log^2(1/r)\tracetwopoint(r)=\traceamplitude>0
\quad\text{in }\C\,,
\end{equation*}
and require the finite-profile exclusion of Proposition~\ref{prop:NF}.

For every gauge group of Definition~\ref{def:D01}, there is a regular \textup{(Q1)} Wilson family~$\mathcal W$ such that, for every strictly increasing~$\mathsf p:\N\to\N$, there are a strictly increasing~$\mathsf q$ and hierarchy data over~$\mathcal W$ \textup{(Q0)} satisfying \textup{Q2--Q6}, with
\begin{equation*}
\mathcal W\longrightarrow S^{\rm mix}\circ\pi_{\rm quo}
\quad\text{along }P=\mathsf p\circ\mathsf q
\quad\text{in the sense of Definition~\ref{def:D09}}\,.
\end{equation*}

For every~$d$, a box stencil $\Sigma_d=[-\varrho_d,\varrho_d]^4\cap\Z^4$ and sections can be chosen gauge invariant, real and $\hypercubic$ covariant, with $\localsection{d}[\mathbf1]=1$, so that, for every $\mathbf c\in V_d$, radial jet~$\mathsf j$ and $0\le q\le d$,
\begin{equation}
\left.\frac{d^q}{dh_{\rm lat}^q}\localsection{d}[\mathbf c](U(h_{\rm lat},\mathsf j))\right|_{h_{\rm lat}=0}
=\left.\frac{d^q}{dh_{\rm lat}^q}\mathbf c(\operatorname{sc}_{h_{\rm lat}}\mathsf j)\right|_{h_{\rm lat}=0}\,.
\end{equation}

